113	    // ==================== 双人押运打卡 ====================
114	
115	    @Test
116	    void escort_requires_two_distinct_custodians_and_rejects_repeat() {
117	        long id = createPlan("ATM-0001", null);
118	        service.approve(id, new ApproveRequest(rid()));
