194	    // ==================== 长短款挂账原子性 ====================
195	
196	    @Test
197	    void mismatch_records_discrepancy_atomically_with_plan_status() {
198	        long id = happyPlanToEscorted("ATM-0001", 150000L);
199	        service.count(id, new CountRequest(rid(), 149000L, "C-01")); // 清点短款 1000
