281	    @Test
282	    void same_request_id_and_params_returns_first_result() {
283	        String requestId = rid();
284	        PlanResponse first = (PlanResponse) service
285	                .createPlan(new CreatePlanRequest(requestId, "ATM-0001", 120000L)).body();
286	        PlanResponse replay = (PlanResponse) service
287	                .createPlan(new CreatePlanRequest(requestId, "ATM-0001", 120000L)).body();
288	        assertEquals(first.id(), replay.id(), "同键同参返回首次结果，不重复建单");
289	        assertEquals(1L, repo.findAllPlans().size());
290	
291	        // 押运打卡同键重放也返回首次结果，不产生重复打卡
292	        long id = first.id();
293	        service.approve(id, new ApproveRequest(rid()));
294	        String checkinRid = rid();
295	        PlanResponse c1 = (PlanResponse) service.checkin(id, new CheckinRequest(checkinRid, "C-01")).body();
296	        PlanResponse c1Replay = (PlanResponse) service.checkin(id, new CheckinRequest(checkinRid, "C-01")).body();
297	        assertEquals(c1.checkinCount(), c1Replay.checkinCount());
298	        assertEquals(1, repo.findCheckins(id).size());
