301	    @Test
302	    void same_request_id_different_params_conflicts_409() {
303	        String requestId = rid();
304	        service.createPlan(new CreatePlanRequest(requestId, "ATM-0001", 120000L));
305	        BusinessException ex = assertThrows(BusinessException.class,
306	                () -> service.createPlan(new CreatePlanRequest(requestId, "ATM-0001", 130000L)));
307	        assertEquals(409, ex.getStatusCode());
308	    }
