310	    // ==================== 并发唯一受理 ====================
311	
312	    @Test
313	    void concurrent_plan_creation_for_same_atm_day_only_one_accepted() throws Exception {
314	        int threads = 8;
315	        ExecutorService pool = Executors.newFixedThreadPool(threads);
316	        CountDownLatch start = new CountDownLatch(1);
317	        AtomicInteger success = new AtomicInteger();
318	        AtomicInteger conflict = new AtomicInteger();
319	        try {
320	            for (int i = 0; i < threads; i++) {
321	                pool.submit(() -> {
322	                    try {
323	                        start.await();
324	                        service.createPlan(new CreatePlanRequest(rid(), "ATM-0001", 100000L));
325	                        success.incrementAndGet();
326	                    } catch (BusinessException e) {
327	                        if (e.getStatusCode() == 409) {
328	                            conflict.incrementAndGet();
329	                        }
330	                    } catch (InterruptedException ignored) {
331	                        Thread.currentThread().interrupt();
332	                    }
333	                });
334	            }
335	            start.countDown();
336	        } finally {
337	            pool.shutdown();
338	            assertTrue(pool.awaitTermination(15, TimeUnit.SECONDS));
339	        }
340	        assertEquals(1, success.get(), "同一 ATM 当日并发编制只能唯一受理");
341	        assertEquals(threads - 1, conflict.get());
342	        assertEquals(1L, repo.findPlanByAtmAndDate(
343	                repo.findAtmByCode("ATM-0001").orElseThrow().id(),
344	                java.time.LocalDate.parse("2026-09-20")).stream().count());
345	    }
346	
347	    @Test
348	    void concurrent_checkins_from_distinct_custodians_both_accepted_and_ordered() throws Exception {
349	        long id = createPlan("ATM-0001", null);
350	        service.approve(id, new ApproveRequest(rid()));
351	
352	        ExecutorService pool = Executors.newFixedThreadPool(2);
353	        CountDownLatch start = new CountDownLatch(1);
354	        Future<?> f1 = pool.submit(() -> {
355	            try {
356	                start.await();
357	            } catch (InterruptedException e) {
358	                Thread.currentThread().interrupt();
359	                throw new RuntimeException(e);
360	            }
361	            service.checkin(id, new CheckinRequest(rid(), "C-01"));
362	        });
363	        Future<?> f2 = pool.submit(() -> {
364	            try {
365	                start.await();
366	            } catch (InterruptedException e) {
367	                Thread.currentThread().interrupt();
368	                throw new RuntimeException(e);
369	            }
370	            service.checkin(id, new CheckinRequest(rid(), "C-02"));
371	        });
372	        start.countDown();
373	        f1.get(10, TimeUnit.SECONDS);
374	        f2.get(10, TimeUnit.SECONDS);
375	        pool.shutdown();
376	
377	        var checkins = repo.findCheckins(id);
378	        assertEquals(2, checkins.size());
379	        assertEquals(1, checkins.get(0).seq());
380	        assertEquals(2, checkins.get(1).seq(), "双人打卡按时间定序");
381	        assertEquals(PlanStatus.ESCORTED, repo.findPlanById(id).orElseThrow().getStatus());
382	    }
