384	    // ==================== 封存终态与迟到数据 ====================
385	
386	    @Test
387	    void seal_is_terminal_and_late_data_only_records_late_events() {
388	        long id = happyPlanToEscorted("ATM-0001", 150000L);
389	        service.count(id, new CountRequest(rid(), 150000L, "C-01"));
390	        service.deviceConfirm(id, new DeviceConfirmRequest(rid(), 150000L));
391	
392	        PlanResponse sealed = (PlanResponse) service.seal(id, new SealRequest(rid())).body();
393	        assertEquals(PlanStatus.SEALED.name(), sealed.status());
394	        assertNotNull(sealed.sealedAt());
395	
