package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDate;

/**
 * 节假日峰值预测并自动生成临时加钞计划请求。
 * holidayDate 须存在于合成节假日日历，且当前 UTC 日期须落在节前 3 日窗口内。
 */
public record ForecastGenerateRequest(
        @NotBlank String requestId,
        @NotNull LocalDate holidayDate
) {
}

package com.example.starter.api;

import java.time.LocalDate;
import java.util.List;

/**
 * 节假日峰值预测结果。逐 ATM 给出预测峰值、150% 阈值与是否生成临时计划；
 * 未生成的 reason 说明原因（未超阈值/ATM 冻结/当日已存在临时计划）。
 */
public record ForecastResponse(
        LocalDate holidayDate,
        String holidayName,
        int peakFactorBp,
        LocalDate windowStart,
        LocalDate windowEnd,
        List<Item> results
) {
    public record Item(
            String atmCode,
            long predictedPeak,
            long threshold,
            boolean generated,
            Long planId,
            String planStatus,
            String reason
    ) {
    }
}

package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 让路计划恢复执行请求。仅 YIELDED 状态可恢复；
 * 须满足同一 ATM 无执行中计划且按排队位置轮到该计划。
 */
public record ResumeRequest(
        @NotBlank String requestId
) {
}

package com.example.starter.api;

import com.example.starter.repo.FastTrackAuditRow;

import java.time.Instant;

/**
 * 快速通道结论留痕响应。decision：AUTO_APPROVED 快速放行 / CONFLICT_WIN 冲突优先 /
 * CONFLICT_YIELD 冲突让路 / RESUMED 恢复执行。
 */
public record FastTrackAuditResponse(
        Long id,
        long planId,
        String decision,
        String detail,
        Instant createdAt
) {
    public static FastTrackAuditResponse of(FastTrackAuditRow row) {
        return new FastTrackAuditResponse(row.id(), row.planId(), row.decision(), row.detail(), row.createdAt());
    }
}

