@Transactional
public Outcome resume(long planId, ResumeRequest req) {
    String fingerprint = fingerprint("RESUME", req.requestId(), String.valueOf(planId));
    return withIdempotency(req.requestId(), "RESUME", fingerprint, planId, PlanResponse.class, () -> {
        PlanRow plan = lockPlan(planId);
        if (plan.getSealedAt() != null) return lateOutcome(plan, "RESUME", ...);
        if (plan.getStatus() != PlanStatus.YIELDED) throw 409;
        Atm atm = repo.findAtmById(plan.getAtmId()).orElseThrow(...);
        if (atm.frozen()) throw 409;
        List<PlanRow> executing = repo.findExecutingByAtm(plan.getAtmId());
        if (!executing.isEmpty()) throw new BusinessException(409, "同一 ATM 同时刻只允许一张执行中加钞单，当前执行中计划: " + executing.get(0).getPlanNo());
        List<PlanRow> yielded = repo.findYieldedByAtm(plan.getAtmId());
        if (!yielded.isEmpty() && yielded.get(0).getId() != plan.getId()) throw 409 "排队位置 " + ... + " 的计划未恢复，按队列顺序受理";
        Instant now = ...;
        plan.setStatus(APPROVED);
        plan.setApprovedAt(now);
        plan.setEscortDeadline(now + (TEMPORARY ? 2h : 4h));
        repo.updatePlan(plan);
        if (plan.getPlanType() == TEMPORARY) repo.insertFastTrackAudit(plan.getId(), "RESUMED", ...);
        return ok;
    });
}
